#!/usr/bin/env bash\n# test_post_zen_comment.sh - verifies that the script constructs the correct curl command.\n\nset -euo pipefail\n\n# Mock rationale: replace curl with echo to capture the command without network activity.\nexport CURL_CMD=echo\n\n# Set required env vars\nexport GITHUB_TOKEN="fake-token"\nexport GITHUB_REPOSITORY="owner/repo"\nexport PR_NUMBER="42"\n\n# Capture output\noutput=$(bash "$(dirname "$0")/../src/post_zen_comment.sh")\n\n# Check that output contains the API URL with correct repo and PR number\nif [[ "$output" != *"https://api.github.com/repos/owner/repo/issues/42/comments"* ]]; then\n  echo "FAIL: API URL not found in output"\n  exit 1\nfi\n\n# Check that output contains one of the known quotes\nfound=0\nquotes=(\n"Peace comes from within. Do not seek it elsewhere."\n"The journey of a thousand miles begins with a single step."\n"Silence is a source of great strength."\n"Let go or be dragged."\n"The obstacle is the path."\n)\nfor q in "${quotes[@]}"; do\n  if [[ "$output" == *"$q"* ]]; then\n    found=1\n    break\n  fi\ndone\n\nif [[ $found -eq 0 ]]; then\n  echo "FAIL: Quote not found in output"\n  exit 1\nfi\n\necho "PASS"
